#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="$ROOT/app/src/main/assets/audio"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
command -v espeak >/dev/null || { echo 'Install eSpeak with Persian (fa) voice.' >&2; exit 1; }
command -v ffmpeg >/dev/null || { echo 'Install ffmpeg.' >&2; exit 1; }
# The checked-in MP3 files are generated from the Persian clinical catalog.
# This script documents the deterministic audio conversion pipeline; the
# catalog export TSV is generated by the Kotlin helper used during development.
if [[ ! -f "$ROOT/tools/audio-lines.tsv" ]]; then
  echo 'Create audio-lines.tsv from ClinicalPathwaysFa before regenerating assets.' >&2
  exit 1
fi
mkdir -p "$OUT"
find "$OUT" -maxdepth 1 -type f -name '*.mp3' -delete
while IFS=$'\t' read -r hash text; do
  [[ -n "$hash" && -n "$text" ]] || continue
  espeak -v fa -s 145 -a 170 -w "$TMP/$hash.wav" "$text"
  ffmpeg -y -loglevel error -i "$TMP/$hash.wav" -codec:a libmp3lame -b:a 64k "$OUT/$hash.mp3"
done < "$ROOT/tools/audio-lines.tsv"
echo "Generated audio files in $OUT"
